import json, urllib.request, datetime
from playwright.sync_api import sync_playwright
prov=json.load(open('/tmp/prov.json')); B='http://localhost:8765/'; erros=[]; n=0
def api(o): return json.loads(urllib.request.urlopen(urllib.request.Request(B+'exec', data=json.dumps(o).encode())).read())
def ok(m):
    global n; n+=1; print('ok ',m)
em=lambda d:(datetime.date.today()+datetime.timedelta(days=d)).isoformat()
with sync_playwright() as p:
    br=p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    pg=br.new_page(viewport={'width':1366,'height':900})
    pg.on('console', lambda m: erros.append(m.text) if m.type=='error' and 'cdnjs' not in str(m.location) and 'ERR_FAILED' not in m.text else None)
    pg.on('pageerror', lambda e: erros.append('PAGEERR '+str(e)))
    pg.on('dialog', lambda d: d.accept())
    pg.add_init_script("localStorage.setItem('jornada_gas_url','http://localhost:8765/exec')")
    pg.goto(B); pg.fill('#login-email','marques.marcela@estacio.br'); pg.fill('#login-senha',prov['admin']); pg.click('#btn-entrar')
    pg.wait_for_selector('#form-troca:not([hidden])'); pg.fill('#troca-atual',prov['admin']); pg.fill('#troca-nova','Admin2026b'); pg.fill('#troca-conf','Admin2026b'); pg.click('#form-troca button.primario')
    pg.wait_for_function("document.body.dataset.tela==='app'")
    assert 'Cobrança' in pg.inner_text('#menu'); ok('menu mostra Cobrança no lugar do Financeiro')
    tok0=pg.evaluate("JSON.parse(localStorage.getItem('jornada_sessao')).token")
    r=api({'acao':'formandos.ops','token':tok0,'ops':[{'op':'set','col':'students','id':'202301000105','data':{'id':'202301000105','mat':'202301000105','nome':'Engaja Exemplo 6','upd':1}}]}); assert r.get('ok'), r
    pg.goto(B+'#/s/financeiro'); pg.wait_for_timeout(2500)
    f=[x for x in pg.frames if 'modulos/cobranca' in x.url][0]; f.wait_for_selector('.regua', timeout=15000)
    f.wait_for_function("document.querySelectorAll('tr[data-mat]').length===2", timeout=15000)
    assert '1º contato' in f.inner_text('.regua') and f.inner_text('#c-fila')=='2'; ok('fila do dia: 2 inadimplentes na 1ª etapa da régua')
    assert '2 inadimplente(s)' in f.inner_text('#sub') and '1.600,00' in f.inner_text('#sub'); ok('carteira Ímpar: 2 inadimplentes, R$ 1.600,00')
    pg.screenshot(path='/home/claude/testes/tela_cobranca_fila.png')
    assert '🎓 Formando' in f.inner_text('tr[data-mat="202301000105"]') and '🎓' not in f.inner_text('tr[data-mat="202301000102"]'); ok('tag de formando só no aluno que está no Formandos')
    mats=f.evaluate("[...document.querySelectorAll('tr[data-mat]')].map(t=>t.dataset.mat)")
    m1,m2=mats[0],mats[1]
    f.click(f'tr[data-mat="{m1}"]'); f.wait_for_selector('#f')
    assert 'wa.me/55' in f.get_attribute('#abrir-wa','href'); ok('ficha tem WhatsApp com a mensagem da etapa')
    f.fill('#f [name=obs]','Aluno disse que paga semana que vem'); f.click('#f button.primario'); f.wait_for_function(f"!document.querySelector('tr[data-mat=\"{m1}\"]')", timeout=10000)
    ok('contato registrado tira o aluno da fila da etapa')
    f.click(f'#abas [data-aba=carteira]'); f.click(f'tr[data-mat="{m2}"]'); f.wait_for_selector('#f'); f.click('[data-modo=promessa]'); f.wait_for_selector('#f [name=valor]')
    f.fill('#f [name=valor]','350,00'); f.fill('#f [name=data]',em(3)); f.click('#f button.primario'); f.wait_for_function("document.getElementById('modal').hidden", timeout=10000)
    f.click('#abas [data-aba=promessas]'); f.wait_for_timeout(300); assert 'No prazo' in f.inner_text('#area') and f.inner_text('#c-prom')=='1'; ok('promessa registrada aparece no prazo')
    f.click(f'#abas [data-aba=carteira]'); f.click(f'tr[data-mat="{m1}"]'); f.wait_for_selector('#f'); f.click('[data-modo=acordo]'); f.wait_for_selector('#f [name=total]')
    f.fill('#f [name=entrada]','250'); f.fill('#f [name=entradaVenc]',em(1)); f.fill('#f [name=parcelas]','2'); f.fill('#f [name=primeiroVenc]',em(31))
    assert '2x de' in f.inner_text('#simula'); f.click('#f button.primario'); f.wait_for_function("document.getElementById('modal').hidden", timeout=10000)
    f.click('#abas [data-aba=acordos]'); f.wait_for_timeout(300); assert f.locator('[data-parcela]').count()==3; ok('acordo com entrada + 2 parcelas')
    f.check('[data-parcela="0"]'); f.wait_for_timeout(1500); assert f.locator('[data-parcela="0"]').is_checked(); ok('entrada marcada como paga')
    pg.screenshot(path='/home/claude/testes/tela_cobranca_acordos.png')
    f.click('#abas [data-aba=evolucao]'); f.wait_for_timeout(300); assert 'Acertaram o valor' in f.inner_text('#area') and 'Promessas de pagamento (1)' in f.inner_text('#area'); ok('evolução mostra quitaram, parcial, promessas e acordos')
    tok=pg.evaluate("JSON.parse(localStorage.getItem('jornada_sessao')).token")
    regs=api({'acao':'financeiro.listar','token':tok})['regs']; assert sorted(r['resultado'] for r in regs)==['Acordo fechado','Pagou','Prometeu pagar'] or len(regs)==3, [r['resultado'] for r in regs]; ok('contato, promessa e acordo viram acionamentos (produtividade)')
    pg.screenshot(path='/home/claude/testes/tela_cobranca_evolucao.png')
    br.close()
print(n,'passos ok'); print('erros:', erros or 'nenhum')
